def split_payment(total, num_payers):
    """Divides a total amount evenly among payers, handling remainders."""
    amount_per_payer = total // num_payers
    remainder = total % num_payers
    if remainder:
        return [amount_per_payer + 1] * (num_payers - remainder) + [amount_per_payer] * remainder
    return [amount_per_payer] * num_payers

def apply_merchant_fee(amount, fee_rate):
    """Calculates the merchant fee based on a percentage rate."""
    return int(amount * fee_rate)

def process_refund(amount, refund_percentage):
    """Computes the refund amount based on a percentage."""
    return int(amount * refund_percentage) 
